<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>Account Statement</h1><p>Income, expense and server-calculated running balance</p></div></header><div class="metric-grid"><div class="metric-card"><span>Income</span><strong><?= number_format($income,2) ?></strong></div><div class="metric-card"><span>Expense</span><strong><?= number_format($expense,2) ?></strong></div><div class="metric-card"><span>Net Balance</span><strong><?= number_format($balance,2) ?></strong></div></div><form class="filter-bar filter-bar--compact" method="get"><div class="module-field"><label>From</label><input class="module-input" name="from_date" type="date" value="<?= e($from) ?>"></div><div class="module-field"><label>To</label><input class="module-input" name="to_date" type="date" value="<?= e($to) ?>"></div><div class="module-field"><label>Search</label><input class="module-input" name="search" value="<?= e($search) ?>"></div><button class="btn btn--primary">Apply</button></form><section class="module-card"><div class="module-card__body"><div class="table-tools"><div class="export-actions"><button class="export-button" type="button" onclick="window.print()">Print</button></div></div><table class="data-table"><thead><tr><th>Date</th><th>Description</th><th>Expense</th><th>Income</th><th>Net Balance</th><th>Reference</th></tr></thead><tbody><?php if(!$transactions):?><tr><td colspan="6">No records found.</td></tr><?php else:foreach($transactions as$t):?><tr><td><?= e($t['transaction_date']) ?></td><td><?= e($t['description']) ?></td><td><?= $t['transaction_type']==='expense'?number_format((float)$t['amount'],2):'—' ?></td><td><?= $t['transaction_type']==='income'?number_format((float)$t['amount'],2):'—' ?></td><td><?= number_format((float)$t['balance'],2) ?></td><td><?= e($t['reference_type']??'') ?></td></tr><?php endforeach;endif ?></tbody></table></div></section></div></div></main>
